create policy "product files members read" on storage.objects for select to authenticated using (bucket_id = 'product-files' and exists (select 1 from public.organization_members m where m.organization_id::text = (storage.foldername(name))[1] and m.user_id = auth.uid()));
create policy "product files writers upload" on storage.objects for insert to authenticated with check (bucket_id = 'product-files' and exists (select 1 from public.organization_members m where m.organization_id::text = (storage.foldername(name))[1] and m.user_id = auth.uid() and m.role::text in ('owner','admin','manager')));
create policy "product files writers delete" on storage.objects for delete to authenticated using (bucket_id = 'product-files' and exists (select 1 from public.organization_members m where m.organization_id::text = (storage.foldername(name))[1] and m.user_id = auth.uid() and m.role::text in ('owner','admin','manager')));